function patchHealthDataSettingItem(
  settings: health_data_settings_data[],
  group: number,
  label: string,
  value: string | undefined | null,//
): health_data_settings_data[] {
  const groupHasLabel = !!settings[group]?.items?.some((row) => row.id === label);
  return settings.map((g, gi) => {
    const shouldVisit = groupHasLabel ? gi === group : !!g.items?.some((row) => row.id === label);
    if (!shouldVisit) {
      return g;
    }
    return {
      ...g,
      items: g.items.map((row) => {
        if (row.id !== label) {
          return row;
        }
        const nextRaw = value === undefined || value === null ? '' : value;
        const nextVal =
          typeof nextRaw === 'string' && nextRaw.endsWith('.') && !isHealthDataDateItem(row)
            ? `${nextRaw}0`
            : nextRaw;
        return { ...row, value: nextVal };
      }),
    };
  });
}

function readHealthDateFieldRaw(params: {
  healthData?: QueryPatientHealth_Data;
  language: string;
  label: string;
  group: number;
  settings: health_data_settings_data[] | health_data_settings_data_Item[] | any[];
}): string {
  if (params.healthData?.id) {
    const key = params.language.charAt(0).toLowerCase() + params.language.slice(1);
    const fromRecord = params.healthData[key as keyof QueryPatientHealth_Data];
    return fromRecord == null ? '' : String(fromRecord);
  }
  const settings = params.settings;
  if (!Array.isArray(settings)) {
    return '';
  }
  const groups = settings as health_data_settings_data[];
  const groupHasItems = groups.some((g) => Array.isArray(g?.items));
  if (groupHasItems) {
    const inGroup = groups[params.group]?.items?.find((row) => row.id === params.label)?.value;
    if (inGroup != null && String(inGroup).trim() !== '') {
      return String(inGroup);
    }
    for (const g of groups) {
      const found = g?.items?.find((row) => row.id === params.label)?.value;
      if (found != null && String(found).trim() !== '') {
        return String(found);
      }
    }
    return inGroup == null ? '' : String(inGroup);
  }
  const flat = settings as health_data_settings_data_Item[];
  const found = flat.find((row) => row?.id === params.label)?.value;
  return found == null ? '' : String(found);
}

function formatHealthDateFieldDisplay(raw: string): string {
  const value = raw.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }
  if (isHealthDataObstetricDatePattern(value)) {
    const formatted = moment(value).format('YYYY-MM-DD');
    return formatted === 'Invalid date' ? global.i18n.t('PleaseSelect') : formatted;
  }
  return global.i18n.t('PleaseSelect');
}

